import finderFuncOrModuleExports from '@medv/finder'

let finder = finderFuncOrModuleExports
if (typeof finder !== 'function') {
  // TODO - Rollup failed to import the module properly.
  // import * as finderFuncOrModuleExports from '@medv/finder'
  // does not help.
  finder = (finderFuncOrModuleExports as any).default
}

export function isEventTarget(input: any): boolean {
  return !!(
    input.addEventListener &&
    input.removeEventListener &&
    input.dispatchEvent
  )
}

export function resolveEventTargetSelector(selector: string): EventTarget[] {
  if (selector === '@window') {
    return [window]
  }
  if (selector === '@document') {
    return [document]
  }
  return Array.from(document.querySelectorAll(selector))
}

export function generateEventTargetSelector(
  eventTarget: EventTarget,
): string | undefined {
  if (eventTarget === window) {
    return '@window'
  }
  if (eventTarget === document) {
    return '@document'
  }
  const node = eventTarget as Node
  if (node.nodeType === Node.ELEMENT_NODE) {
    // Generate a CSS selector for the Element
    return finder(eventTarget as Element)
  }
}

export interface Point {
  x: number
  y: number
}

export type EventSupported = MouseEvent | TouchEvent

export function getEventTargetPoint(event: EventSupported): Point {
  if ((event as MouseEvent).clientX !== undefined) {
    return {
      x: (event as MouseEvent).clientX,
      y: (event as MouseEvent).clientY,
    }
  }

  const eventType = event.type
  const singleTouch =
    eventType === 'touchend'
      ? (event as TouchEvent).changedTouches?.[0]
      : (event as TouchEvent).touches?.[0]
  if (!singleTouch) {
    throw new Error('A touch has not been found')
  }
  return {
    x: singleTouch.clientX,
    y: singleTouch.clientY,
  }
}

/**
 * This can be used to track the state and qualities
 * of a touch, like how long it was pressed, how far the user
 * moved finger, and you can set thresholds for time and distance
 */
export class TouchTracker {
  // user might have started with finger down, so we don't start
  // on 'up' state.  We have to wait until finger goes down
  // to begin
  private tapState: 'start' | 'up' | 'touching' | 'dragging' = 'start'
  private distanceThreshold = 50
  private timeThreshold = 500
  private origin: Point
  private originTime = 0
  private current: Point
  private currentTime = 0

  constructor(distanceThreshold = 50, timeThreshold = 500) {
    this.distanceThreshold = distanceThreshold
    this.timeThreshold = timeThreshold

    this.origin = { x: 0, y: 0 }
    this.current = { x: 0, y: 0 }
    this.originTime = new Date().getTime()
    this.currentTime = this.originTime
  }
  onPointerDown(event: EventSupported): void {
    this.tapState = 'touching'

    const eventTargetPoint: Point = this.getEventTargetPoint(event)

    this.origin = eventTargetPoint
    this.current = eventTargetPoint
    this.originTime = event.timeStamp
  }
  onPointerMove(event: EventSupported): void {
    if (this.tapState === 'touching') {
      this.tapState = 'dragging'
    }
    this.current = this.getEventTargetPoint(event)
    this.currentTime = event.timeStamp
  }
  onPointerUp(event: EventSupported): void {
    if (this.tapState !== 'start') {
      this.tapState = 'up'
    }
    this.current = this.getEventTargetPoint(event)
    this.currentTime = event.timeStamp
  }
  isDragging(): boolean {
    return this.tapState === 'dragging'
  }
  isDone(): boolean {
    return this.tapState === 'up'
  }
  movedLong(): boolean {
    const dX = this.current.x - this.origin.x
    const dY = this.current.y - this.origin.y
    const distance = dX * dX + dY * dY

    // distance threshold passed in to constructor as pixel squared value
    // so we don't have to square it here on every function call
    return distance > this.distanceThreshold
  }
  pressedLong(): boolean {
    if (this.tapState === 'up') {
      return this.currentTime - this.originTime > this.timeThreshold
    } else {
      return false
    }
  }

  private getEventTargetPoint(event: EventSupported): Point {
    return getEventTargetPoint(event)
  }
}

export type PanEvent = {
  index: number
  start: boolean
  end: boolean
  pinch: boolean
  screenX1: number
  screenY1?: number
  screenX2?: number
  screenY2?: number
  timeStamp?: number
  numberOfTouches?: number
  clientX1: number
  clientY1: number
  clientX2?: number
  clientY2?: number
}

enum PanState {
  None = 1,
  Start,
  Move,
}

export class PanEventHandler {
  private selectionIsPresent = false

  private prePanCheckEventX: number
  private panState: PanState = PanState.None
  private callback: (event: PanEvent) => void

  constructor(callback: (event: PanEvent) => void) {
    this.callback = callback
  }

  public setSelectionIsPresent = (selectionIsPresent: boolean) => {
    this.selectionIsPresent = selectionIsPresent
  }

  public prePanCheckEvent = (event: Event): void => {
    this.prePanCheckEventX = (event as TouchEvent).touches[0].screenX
  }

  public endEvent = (event: Event): void => {
    if (this.selectionIsPresent) {
      return
    }

    if (this.panState === PanState.None) {
      return
    }

    const touchEvent = event as TouchEvent

    if (touchEvent.changedTouches.length === 1) {
      this.callback({
        index: -1,
        start: false,
        end: true,
        pinch: false,
        screenX1: touchEvent.changedTouches[0].screenX,
        screenY1: touchEvent.changedTouches[0].screenY,
        screenX2: undefined,
        screenY2: undefined,
        timeStamp: touchEvent.timeStamp,
        numberOfTouches: touchEvent.touches.length,
        clientX1: touchEvent.changedTouches[0].clientX,
        clientY1: touchEvent.changedTouches[0].clientY,
      })
    } else if (touchEvent.changedTouches.length === 2) {
      this.callback({
        index: -1,
        start: false,
        end: true,
        pinch: true,
        screenX1: touchEvent.changedTouches[0].screenX,
        screenY1: touchEvent.changedTouches[0].screenY,
        screenX2: touchEvent.changedTouches[1].screenX,
        screenY2: touchEvent.changedTouches[1].screenY,
        timeStamp: undefined,
        numberOfTouches: touchEvent.touches.length,
        clientX1: touchEvent.changedTouches[0].clientX,
        clientY1: touchEvent.changedTouches[0].clientY,
        clientX2: touchEvent.changedTouches[1].clientX,
        clientY2: touchEvent.changedTouches[1].clientY,
      })
    }

    this.panState = PanState.None
  }

  public moveEvent = (event: Event): void => {
    if (this.selectionIsPresent) {
      return
    }

    const panEvent: PanEvent | null = this.getPanEventForMove(event)

    if (!panEvent) {
      return
    }

    this.callback(panEvent)
  }

  private getPanEventForMove(event: Event): PanEvent | null {
    if (this.panState === PanState.None) {
      const touchEvent = event as TouchEvent

      const shouldPanStart =
        touchEvent.touches[0].screenX - this.prePanCheckEventX > 1 ||
        touchEvent.touches[0].screenX - this.prePanCheckEventX < -1

      if (shouldPanStart) {
        this.panState = PanState.Start
      }
    }

    const touchEvent = event as TouchEvent

    let panEvent: PanEvent | null = null

    switch (this.panState) {
      case PanState.None:
        break
      case PanState.Start:
        panEvent = this.getMoveStartEvent(touchEvent)
        this.panState = PanState.Move
        break
      case PanState.Move:
        panEvent = this.getMoveContinueEvent(touchEvent)
        break
      default:
        break
    }

    return panEvent
  }

  private getMoveStartEvent(event: Event): PanEvent | null {
    const touchEvent = event as TouchEvent

    if (touchEvent.touches.length === 1) {
      return {
        index: -1,
        start: true,
        end: false,
        pinch: false,
        screenX1: touchEvent.touches[0].screenX,
        screenY1: touchEvent.touches[0].screenY,
        screenX2: undefined,
        screenY2: undefined,
        timeStamp: touchEvent.timeStamp,
        numberOfTouches: touchEvent.touches.length,
        clientX1: touchEvent.touches[0].clientX,
        clientY1: touchEvent.touches[0].clientY,
      }
    } else if (touchEvent.touches.length === 2) {
      return {
        index: -1,
        start: true,
        end: false,
        pinch: true,
        screenX1: touchEvent.touches[0].screenX,
        screenY1: touchEvent.touches[0].screenY,
        screenX2: touchEvent.touches[1].screenX,
        screenY2: touchEvent.touches[1].screenY,
        timeStamp: undefined,
        numberOfTouches: touchEvent.touches.length,
        clientX1: touchEvent.touches[0].clientX,
        clientY1: touchEvent.touches[0].clientY,
        clientX2: touchEvent.touches[1].clientX,
        clientY2: touchEvent.touches[1].clientY,
      }
    }

    return null
  }

  private getMoveContinueEvent(event: Event): PanEvent | null {
    const touchEvent = event as TouchEvent
    if (touchEvent.touches.length === 1) {
      return {
        index: -1,
        start: false,
        end: false,
        pinch: false,
        screenX1: touchEvent.touches[0].screenX,
        screenY1: undefined,
        screenX2: undefined,
        screenY2: undefined,
        timeStamp: undefined,
        numberOfTouches: touchEvent.touches.length,
        clientX1: touchEvent.touches[0].clientX,
        clientY1: touchEvent.touches[0].clientY,
      }
    } else if (touchEvent.touches.length === 2) {
      return {
        index: -1,
        start: false,
        end: false,
        pinch: true,
        screenX1: touchEvent.touches[0].screenX,
        screenY1: touchEvent.touches[0].screenY,
        screenX2: touchEvent.touches[1].screenX,
        screenY2: touchEvent.touches[1].screenY,
        timeStamp: undefined,
        numberOfTouches: touchEvent.touches.length,
        clientX1: touchEvent.touches[0].clientX,
        clientY1: touchEvent.touches[0].clientY,
        clientX2: touchEvent.touches[1].clientX,
        clientY2: touchEvent.touches[1].clientY,
      }
    }

    return null
  }
}
