import { Service } from './service'
import { resolveEventTargetSelector } from './util'

export type EventListenerGenerator = (target: EventTarget) => EventListener

export abstract class EventListenerService extends Service {
  private lastUsedID = 0
  private registeredEventListenerRemovers: { [id: number]: Function[] } = {}

  protected registerListenerForTargets(
    target: string,
    type: string,
    listener: EventListener,
  ): number {
    const targets = resolveEventTargetSelector(target)
    const listenerRemovers = targets.map((resolvedTarget: EventTarget) => {
      resolvedTarget.addEventListener(type, listener)
      return (): void => {
        resolvedTarget.removeEventListener(type, listener)
      }
    })
    this.lastUsedID = this.lastUsedID + 1
    this.registeredEventListenerRemovers[this.lastUsedID] = listenerRemovers
    return this.lastUsedID
  }

  protected registerListenerForEachTarget(
    target: string,
    type: string,
    generator: EventListenerGenerator,
  ): number {
    const targets = resolveEventTargetSelector(target)
    const listenerRemovers = targets.map((resolvedTarget: EventTarget) => {
      const listener = generator(resolvedTarget)
      resolvedTarget.addEventListener(type, listener)
      return () => {
        resolvedTarget.removeEventListener(type, listener)
      }
    })
    this.lastUsedID = this.lastUsedID + 1
    this.registeredEventListenerRemovers[this.lastUsedID] = listenerRemovers
    return this.lastUsedID
  }

  protected registerListener(): number {
    this.lastUsedID = this.lastUsedID + 1
    this.registeredEventListenerRemovers[this.lastUsedID] = []
    return this.lastUsedID
  }

  protected addListenerToTarget(
    type: string,
    target: EventTarget,
    listenerId: number,
    listener: EventListener,
  ): void {
    const listenerRemovers = this.registeredEventListenerRemovers[listenerId]
    target.addEventListener(type, listener)
    const remover = (): void => {
      target.removeEventListener(type, listener)
    }
    listenerRemovers.push(remover)
  }

  protected removeEventListeners(listenerID: number): void {
    this.registeredEventListenerRemovers[listenerID]?.forEach((remove) =>
      remove(),
    )
  }

  protected peekId(): number {
    return this.lastUsedID + 1
  }
}
