import { generateEventTargetSelector, isEventTarget } from './util'

export function marshalObject(obj: any): any {
  return JSON.parse(
    JSON.stringify(obj, (_, value) => {
      if (value && isEventTarget(value)) {
        return generateEventTargetSelector(value)
      }
      return value
    }),
  )
}

export const EVENT_PROPERTIES = [
  'type',
  'target',
  'currentTarget',
  'eventPhase',
  'bubbles',
  'cancelable',
  'defaultPrevented',
  'composed',
  'timeStamp',
  'srcElement',
  'returnValue',
  'cancelBubble',
  'path',
  'composedPath',
]

export const UI_EVENT_PROPERTIES = ['view', 'detail']

export function marshalEvent(
  event: Event,
  enumeratedProperties: string[] = [],
): any {
  let propertiesToEnumerate = [...EVENT_PROPERTIES, ...enumeratedProperties]
  if (event instanceof UIEvent) {
    propertiesToEnumerate = propertiesToEnumerate.concat(UI_EVENT_PROPERTIES)
  }
  const eventObject: any = {}
  propertiesToEnumerate.forEach((key) => {
    eventObject[key] = (event as any)[key]
  })
  return marshalObject(eventObject)
}
